package authproxy

import (
	"bufio"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"golang.org/x/crypto/argon2"
)

var (
	auditLog   *log.Logger
	auditMu    sync.Mutex
	authTokens = make(map[string]string)
)

func init() {
	f, err := os.OpenFile("/var/log/auth_audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		log.Fatal(err)
	}
	auditLog = log.New(f, "AUDIT: ", log.LstdFlags|log.LUTC)
}

func hashToken(token string) string {
	salt := []byte("static-salt-for-lookup")
	h := argon2.IDKey([]byte(token), salt, 1, 64*1024, 4, 32)
	return hex.EncodeToString(h)
}

func logAuditEvent(event string, remoteAddr string, authenticated bool) {
	auditMu.Lock()
	defer auditMu.Unlock()
	auditLog.Printf("[%s] remote=%s authenticated=%t event=%s",
		time.Now().UTC().Format(time.RFC3339), remoteAddr, authenticated, event)
}

// parseContentLength extracts Content-Length from raw headers.
// Handles the case where multiple Content-Length headers exist per RFC 7230 Section 3.3.2
func parseContentLength(headers []string) (int64, error) {
	var clValues []string
	for _, h := range headers {
		lower := strings.ToLower(strings.TrimSpace(h))
		if strings.HasPrefix(lower, "content-length:") {
			val := strings.TrimSpace(h[len("content-length:"):])
			clValues = append(clValues, val)
		}
	}
	if len(clValues) == 0 {
		return 0, nil
	}
	// Per RFC 7230: if multiple values, they must all be identical
	// Reject the request if values differ
	first := strings.TrimSpace(clValues[0])
	for _, v := range clValues[1:] {
		if strings.TrimSpace(v) != first {
			return 0, fmt.Errorf("conflicting content-length values")
		}
	}
	return strconv.ParseInt(first, 10, 64)
}

// determineTransferEncoding checks if chunked transfer encoding is present
func hasChunkedEncoding(headers []string) bool {
	for _, h := range headers {
		lower := strings.ToLower(strings.TrimSpace(h))
		if strings.HasPrefix(lower, "transfer-encoding:") {
			val := strings.ToLower(strings.TrimSpace(h[len("transfer-encoding:"):]))
			if strings.Contains(val, "chunked") {
				return true
			}
		}
	}
	return false
}

// readRequestBody reads the body based on Content-Length or Transfer-Encoding
// Per RFC 7230 Section 3.3.3: reject messages with both TE and CL
func readRequestBody(reader *bufio.Reader, headers []string) ([]byte, error) {
	chunked := hasChunkedEncoding(headers)
	cl, err := parseContentLength(headers)
	if err != nil {
		return nil, fmt.Errorf("invalid content-length: %w", err)
	}

	// Reject ambiguous requests that have both Transfer-Encoding and Content-Length
	if chunked && cl > 0 {
		return nil, fmt.Errorf("request contains both Transfer-Encoding and Content-Length")
	}

	if chunked {
		return readChunkedBody(reader)
	}

	if cl > 0 {
		if cl > 10*1024*1024 { // 10MB limit
			return nil, fmt.Errorf("content-length exceeds maximum")
		}
		body := make([]byte, cl)
		_, err := io.ReadFull(reader, body)
		return body, err
	}
	return nil, nil
}

func readChunkedBody(reader *bufio.Reader) ([]byte, error) {
	var body []byte
	var totalSize int64
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return nil, err
		}
		line = strings.TrimSpace(line)
		size, err := strconv.ParseInt(line, 16, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid chunk size: %w", err)
		}
		if size < 0 {
			return nil, fmt.Errorf("negative chunk size")
		}
		if size == 0 {
			reader.ReadString('\n') // consume trailing CRLF
			break
		}
		totalSize += size
		if totalSize > 10*1024*1024 { // 10MB limit
			return nil, fmt.Errorf("chunked body exceeds maximum size")
		}
		chunk := make([]byte, size)
		_, err = io.ReadFull(reader, chunk)
		if err != nil {
			return nil, err
		}
		body = append(body, chunk...)
		reader.ReadString('\n') // consume CRLF after chunk
	}
	return body, nil
}

// AuthenticateRequest validates the auth token in the request
func authenticateRequest(headers []string) bool {
	for _, h := range headers {
		lower := strings.ToLower(strings.TrimSpace(h))
		if strings.HasPrefix(lower, "authorization:") {
			token := strings.TrimSpace(h[len("authorization:"):])
			token = strings.TrimPrefix(token, "Bearer ")
			token = strings.TrimPrefix(token, "bearer ")
			hashed := hashToken(token)
			for _, stored := range authTokens {
				if subtle.ConstantTimeCompare([]byte(hashed), []byte(stored)) == 1 {
					return true
				}
			}
		}
	}
	return false
}

// HandleConnection processes a single request per connection (no keep-alive)
func HandleConnection(conn net.Conn, backend string) {
	defer conn.Close()
	conn.SetDeadline(time.Now().Add(30 * time.Second))
	reader := bufio.NewReader(conn)

	// Read request line
	reqLine, err := reader.ReadString('\n')
	if err != nil {
		return
	}

	// Read headers
	var headers []string
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return
		}
		if strings.TrimSpace(line) == "" {
			break
		}
		headers = append(headers, line)
	}

	// Read body
	body, err := readRequestBody(reader, headers)
	if err != nil {
		logAuditEvent("body_read_error: "+err.Error(), conn.RemoteAddr().String(), false)
		conn.Write([]byte("HTTP/1.1 400 Bad Request\r\n\r\n"))
		return
	}

	// Authenticate
	authenticated := authenticateRequest(headers)
	logAuditEvent("request: "+strings.TrimSpace(reqLine), conn.RemoteAddr().String(), authenticated)

	if !authenticated {
		conn.Write([]byte("HTTP/1.1 401 Unauthorized\r\n\r\n"))
		return
	}

	// Forward to backend
	backendConn, err := net.DialTimeout("tcp", backend, 5*time.Second)
	if err != nil {
		conn.Write([]byte("HTTP/1.1 502 Bad Gateway\r\n\r\n"))
		return
	}
	defer backendConn.Close()

	// Reconstruct and forward request, removing Transfer-Encoding
	// and setting accurate Content-Length
	var fwd strings.Builder
	fwd.WriteString(reqLine)
	for _, h := range headers {
		lower := strings.ToLower(strings.TrimSpace(h))
		if strings.HasPrefix(lower, "transfer-encoding:") {
			continue // strip TE header, we'll send with CL
		}
		if strings.HasPrefix(lower, "content-length:") {
			continue // we'll set accurate CL
		}
		fwd.WriteString(h)
	}
	if body != nil && len(body) > 0 {
		fwd.WriteString(fmt.Sprintf("Content-Length: %d\r\n", len(body)))
	}
	fwd.WriteString("\r\n")
	backendConn.Write([]byte(fwd.String()))
	if body != nil {
		backendConn.Write(body)
	}

	// Read and forward response
	respReader := bufio.NewReader(backendConn)
	resp, err := http.ReadResponse(respReader, nil)
	if err != nil {
		conn.Write([]byte("HTTP/1.1 502 Bad Gateway\r\n\r\n"))
		return
	}
	resp.Write(conn)
	resp.Body.Close()
}

func StartProxy(listenAddr, backendAddr string) error {
	ln, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return err
	}
	defer ln.Close()

	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go HandleConnection(conn, backendAddr)
	}
}
